from pathlib import Path
import json,shutil,subprocess,sys
import imageio_ffmpeg
root=Path(__file__).resolve().parent;site=Path('/home/ubuntu/WM-Unreal-data-collection/local_run/site/longvideo/chemical-far');site.mkdir(exist_ok=True)
labels={'baseline':'目前配置（本次复录）','cadence':'固定防闪烁周期','thin':'固定周期＋细小几何检测','stable':'细小几何＋更强历史积累','mip':'纹理采样 +1（诊断）','nofog':'关闭体积雾（诊断）','noreflections':'关闭 Lumen 反射（诊断）','allnofog':'关闭全部雾（诊断）','ss3':'3× 渲染采样，保留雾','ss4':'4× 渲染采样，保留雾','mip2':'纹理采样 +2（诊断）','taa2':'TAA · 2× 渲染采样','taa3':'TAA · 3× 渲染采样','reject4':'TSR 历史保留 4','reject8':'TSR 历史保留 8','zzrepeat_tsr2':'TSR 2× 复测（同一 UE 会话）','zzfinal_taa2':'最终 60 秒录像 · TAA 2×'}
